import UIKit
import Capacitor

/**
 * UIScene lifecycle (Capacitor 8.5+). Generated by `cap migrate`, then corrected by hand.
 *
 * The generated version built its own window with a plain `CAPBridgeViewController()`.
 * That skips Main.storyboard — and with it `AppViewController`, the subclass that
 * registers our hand-written plugins (ShareIntent, MediaControl). Share-to-app and the
 * lock-screen media controls would have silently stopped working on iOS.
 *
 * Info.plist names Main.storyboard for this scene configuration (UISceneStoryboardFile),
 * so UIKit creates the window and the storyboard's root view controller itself and
 * assigns it to `window`. All that is left to do here is to forward the scene events.
 */
class SceneDelegate: UIResponder, UIWindowSceneDelegate {
    var window: UIWindow?

    func scene(_ scene: UIScene, willConnectTo session: UISceneSession, options connectionOptions: UIScene.ConnectionOptions) {
        guard scene is UIWindowScene else { return }
        SceneDelegateProxy.shared.scene(scene, willConnectTo: session, options: connectionOptions)
    }

    func scene(_ scene: UIScene, openURLContexts URLContexts: Set<UIOpenURLContext>) {
        SceneDelegateProxy.shared.scene(scene, openURLContexts: URLContexts)
    }

    func scene(_ scene: UIScene, continue userActivity: NSUserActivity) {
        SceneDelegateProxy.shared.scene(scene, continue: userActivity)
    }
}
